<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Exam Marks</h1><p>Save marks or record an explicit ABS status transactionally.</p></div></header><form class="filter-bar filter-bar--compact"><div class="module-field"><label>Exam / Class / Subject</label><select class="module-select" name="setup" required><option value="">Select setup</option><?php foreach($setups as$s):?><option value="<?=$s['id']?>" <?=$selectedSetup==$s['id']?'selected':''?>><?=e($s['exam_name'].' — '.$s['class_name'].' — '.$s['subject_name'])?></option><?php endforeach?></select></div><button class="btn btn--secondary">Load Students</button></form><?php if($selectedSetup):?><form method="post" action="<?=url('/admin/exams/marks')?>"><?=csrf_field()?><input type="hidden" name="exam_subject_id" value="<?=$selectedSetup?>"><section class="module-card"><div class="module-card__body"><div class="table-scroll"><table class="data-table mobile-register"><thead><tr><th>Registration</th><th>Student</th><th>Marks</th><th>Absent</th><th>Maximum</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><?=e($s['registration_no'])?></td><td><strong><?=e($s['student_name'])?></strong></td><td><input class="module-input" type="number" min="0" max="<?=e($s['total_marks'])?>" step="0.01" name="marks[<?=$s['id']?>]" value="<?=e($s['obtained_marks']??'')?>"></td><td><label class="check-row"><input type="checkbox" name="absent[<?=$s['id']?>]" value="1" <?=!empty($s['is_absent'])?'checked':''?>> ABS</label></td><td><?=e($s['total_marks'])?></td></tr><?php endforeach?></tbody></table></div></div><footer class="module-card__footer"><button class="btn btn--primary">Save Marks</button></footer></section></form><?php endif?></div></div></main>
